package com.ke.ticketsystemke.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="warranty_reminders")
public class WarrantyReminder{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="warranty_claim_id",nullable=false)private WarrantyClaim warrantyClaim;
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="ticket_id",nullable=false)private Ticket ticket;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=50)private WarrantyReminderType reminderType;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private WarrantyReminderStatus status=WarrantyReminderStatus.OPEN;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private WarrantyReminderPriority priority;
 @Column(length=80)private String recipientEmployeeId;@Column(length=160)private String recipientEmployeeNameSnapshot;
 private LocalDate dueDate;@Column(nullable=false)private LocalDate generatedForDate;
 @Column(nullable=false,length=180)private String title;@Column(nullable=false,length=1000)private String message;@Column(length=80)private String pendingActionCode;
 @Column(nullable=false)private boolean overdue;@Column(nullable=false)private int daysOverdue;@Column(nullable=false)private boolean escalated;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private WarrantyEscalationLevel escalationLevel=WarrantyEscalationLevel.NONE;
 @Column(nullable=false,length=300,unique=true)private String deduplicationKey;
 private Instant acknowledgedAt;@Column(length=80)private String acknowledgedByEmployeeId;@Column(length=1000)private String acknowledgementNote;
 private Instant snoozedUntil;@Column(length=80)private String snoozedByEmployeeId;@Column(length=1000)private String snoozeReason;private Instant resolvedAt;@Column(length=500)private String resolvedReason;
 @Column(nullable=false,updatable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;@Version @Column(nullable=false)private Long version;
 @PrePersist void create(){Instant n=Instant.now();if(createdAt==null)createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}
 public Long getId(){return id;}public WarrantyClaim getWarrantyClaim(){return warrantyClaim;}public void setWarrantyClaim(WarrantyClaim v){warrantyClaim=v;}public Ticket getTicket(){return ticket;}public void setTicket(Ticket v){ticket=v;}public WarrantyReminderType getReminderType(){return reminderType;}public void setReminderType(WarrantyReminderType v){reminderType=v;}public WarrantyReminderStatus getStatus(){return status;}public void setStatus(WarrantyReminderStatus v){status=v;}public WarrantyReminderPriority getPriority(){return priority;}public void setPriority(WarrantyReminderPriority v){priority=v;}public String getRecipientEmployeeId(){return recipientEmployeeId;}public void setRecipientEmployeeId(String v){recipientEmployeeId=v;}public String getRecipientEmployeeNameSnapshot(){return recipientEmployeeNameSnapshot;}public void setRecipientEmployeeNameSnapshot(String v){recipientEmployeeNameSnapshot=v;}public LocalDate getDueDate(){return dueDate;}public void setDueDate(LocalDate v){dueDate=v;}public LocalDate getGeneratedForDate(){return generatedForDate;}public void setGeneratedForDate(LocalDate v){generatedForDate=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public String getPendingActionCode(){return pendingActionCode;}public void setPendingActionCode(String v){pendingActionCode=v;}public boolean isOverdue(){return overdue;}public void setOverdue(boolean v){overdue=v;}public int getDaysOverdue(){return daysOverdue;}public void setDaysOverdue(int v){daysOverdue=v;}public boolean isEscalated(){return escalated;}public void setEscalated(boolean v){escalated=v;}public WarrantyEscalationLevel getEscalationLevel(){return escalationLevel;}public void setEscalationLevel(WarrantyEscalationLevel v){escalationLevel=v;}public String getDeduplicationKey(){return deduplicationKey;}public void setDeduplicationKey(String v){deduplicationKey=v;}public Instant getAcknowledgedAt(){return acknowledgedAt;}public void setAcknowledgedAt(Instant v){acknowledgedAt=v;}public String getAcknowledgedByEmployeeId(){return acknowledgedByEmployeeId;}public void setAcknowledgedByEmployeeId(String v){acknowledgedByEmployeeId=v;}public String getAcknowledgementNote(){return acknowledgementNote;}public void setAcknowledgementNote(String v){acknowledgementNote=v;}public Instant getSnoozedUntil(){return snoozedUntil;}public void setSnoozedUntil(Instant v){snoozedUntil=v;}public String getSnoozedByEmployeeId(){return snoozedByEmployeeId;}public void setSnoozedByEmployeeId(String v){snoozedByEmployeeId=v;}public String getSnoozeReason(){return snoozeReason;}public void setSnoozeReason(String v){snoozeReason=v;}public Instant getResolvedAt(){return resolvedAt;}public void setResolvedAt(Instant v){resolvedAt=v;}public String getResolvedReason(){return resolvedReason;}public void setResolvedReason(String v){resolvedReason=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public Long getVersion(){return version;}
}
